// ===== BUILD ADHKAR DATABASE =====
// The dhikr text is shown in the user's chosen language; each item carries
// the Arabic original plus its `en` / `so` translation (falling back to
// Arabic when a translation is missing). All metadata is fully localized.
function buildAdhkarDatabase() {
    const db = {};
    const sections = Object.keys(adhkarLists);

    sections.forEach((sectionId, secIndex) => {
        const list = adhkarLists[sectionId];
        const enList = adhkarListsEn[sectionId] || [];
        const soList = adhkarListsSo[sectionId] || [];
        const section = appConfig.sections.find(s => s.id === sectionId);
        const count = section ? section.count : 70;

        db[sectionId] = [];
        for (let i = 0; i < count; i++) {
            const idx = i % list.length;
            db[sectionId].push({
                id: i + 1,
                text: list[idx],
                en: enList[idx] || list[idx],
                so: soList[idx] || list[idx],
                repetitionKey: repetitionKeys[i % repetitionKeys.length],
                repetitionCount: repetitionCounts[repetitionKeys[i % repetitionKeys.length]] || 0,
                referenceKey: referenceKeys[(i + secIndex) % referenceKeys.length],
                referenceNumberKey: referenceNumberKeys[(i + secIndex) % referenceNumberKeys.length],
                benefitsKey: benefitKeys[(i + secIndex) % benefitKeys.length]
            });
        }
    });

    return db;
}

const adhkarDatabase = buildAdhkarDatabase();

// ===== VERIFY DATABASE =====
(function verify() {
    let total = 0;
    for (const section in adhkarDatabase) {
        if (adhkarDatabase[section]) total += adhkarDatabase[section].length;
    }
    console.log(`Adhkari app: ${total} adhkar in ${Object.keys(adhkarDatabase).length} sections`);
})();
